                            print('Extract button HTML:', btn.evaluate('el => el.outerHTML'))
                            # See if it has an ID
                            btn_id = btn.get_attribute('id')
                            if btn_id:
                                print('Button ID:', btn_id)
                        except Exception as e:
                            print('Error getting btn:', e)

                    # Look for blue circle widget
                    print('\nChecking for widgets or iframes at the bottom right...')
                    # Typically these are fixed position elements at the bottom right
                    script = '''() => {
                        const fixedElements = Array.from(document.querySelectorAll('*')).filter(el => {
                            const style = window.getComputedStyle(el);
                            if (style.position === 'fixed' || style.position === 'absolute') {
                                const rect = el.getBoundingClientRect();
                                if (rect.bottom > window.innerHeight - 150 && rect.right > window.innerWidth - 150) {
                                    return true;
                                }
                            }
                            return false;
                        });
                        return fixedElements.map(el => el.outerHTML).slice(0, 5);
                    }'''
                    fixed_htmls = page.evaluate(script)
                    for html in fixed_htmls:
                        if 'i' in html.lower() or 'svg' in html.lower() or 'circle' in html.lower() or 'btn' in html.lower() or 'chat' in html.lower() or 'help' in html.lower():
