                    print('\nCustom scripts injected:')
                    scripts = page.evaluate('() => Array.from(document.scripts).map(s => s.src || s.innerHTML.substring(0, 100)).filter(s => s.includes(\"استخراج\") || s.includes(\"extract\") || s.includes(\"extension\") || s.includes(\"tamper\"))')
                    for s in scripts:
                        print('Script:', s)
    except Exception as e:
        print('Error:', e)
